import unittest

from shipping import shipping_fee


class ShippingFeeBoundaryTest(unittest.TestCase):
	def test_below_threshold_49999(self):
		self.assertEqual(shipping_fee(49999), 3000)

	def test_at_threshold_50000(self):
		self.assertEqual(shipping_fee(50000), 0)

	def test_above_threshold_50001(self):
		self.assertEqual(shipping_fee(50001), 0)

	def test_zero(self):
		self.assertEqual(shipping_fee(0), 3000)


if __name__ == "__main__":
	unittest.main()
